using System;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class TransferReceipt:System.Web.UI.Page{static AssetBAL S=>new AssetBAL();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name.ToString());protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object List(){var rows=S.List("Transfer",null,null,null);for(var i=rows.Rows.Count-1;i>=0;i--){var status=Convert.ToString(rows.Rows[i]["TransferStatus"]);var completed=string.Equals(status,"Received",StringComparison.OrdinalIgnoreCase)||string.Equals(status,"Rejected",StringComparison.OrdinalIgnoreCase);var dispatched=string.Equals(status,"Dispatched",StringComparison.OrdinalIgnoreCase)||string.Equals(status,"Dispatch",StringComparison.OrdinalIgnoreCase)||string.Equals(status,"In Transit",StringComparison.OrdinalIgnoreCase)||rows.Rows[i]["DispatchDate"]!=DBNull.Value;if(!dispatched||completed)rows.Rows.RemoveAt(i);}return AssetBAL.Rows(rows);}[WebMethod]public static ApiResult Action(long id,string action,string remarks){try{S.Action("Transfer",id,action,remarks,U);return ApiResult.Ok();}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
